class Solution:
    def maxSpending(self, values):
        vals = sorted(v for row in values for v in row)
        return sum(v * (i + 1) for i, v in enumerate(vals))

c.cpp:
class Solution {
public:
    long long maxSpending(vector<vector<int>>& values) {
        vector<int> vals;
        for (auto& row : values) vals.insert(vals.end(), row.begin(), row.end());
        sort(vals.begin(), vals.end());
        long long ans = 0;
        for (int i = 0; i < vals.size(); i++) ans += (long long)vals[i] * (i + 1);
        return ans;
    }
};

c.java:
class Solution {
    public long maxSpending(int[][] values) {
        List<Integer> vals = new ArrayList<>();
        for (int[] row : values) for (int v : row) vals.add(v);
        Collections.sort(vals);
        long ans = 0;
        for (int i = 0; i < vals.size(); i++) ans += (long) vals.get(i) * (i + 1);
        return ans;
    }
}

